import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    static class 小猫 {
        void 打招呼() {
        }

        int 要鱼干(int 几根) {
            return 几根 * 2;
        }
    }

    public static void main(String[] args) {
        List<String> 招式们 = new ArrayList<>();
        for (Method 一招 : 小猫.class.getDeclaredMethods()) {
            招式们.add(一招.getName() + " " + 一招.getParameterCount());
        }
        Collections.sort(招式们);
        for (String 一行 : 招式们) {
            System.out.println(一行);
        }
    }
}

import java.lang.reflect.Field;

public class Main {
    static class 小猫 {
        private String 名字 = "小橘";
        private int 小鱼干 = 3;
    }

    public static void main(String[] args) throws Exception {
        小猫 橘 = new 小猫();
        Field 骨头 = 小猫.class.getDeclaredField("小鱼干");
        骨头.setAccessible(true);
        骨头.set(橘, 8);
        System.out.println(骨头.get(橘));
        System.out.println(橘.名字);
    }
}
